# ! [feature (proc_macro_span)] use proc_macro :: { Span , TokenStream } ; use std :: fs ; use syn :: { parse_macro_input , LitStr } ; # [proc_macro] pub fn get_svg_defs (input : TokenStream) -> TokenStream { let source = { let input = parse_macro_input ! (input as LitStr) . value () ; let span = Span :: call_site () ; span . source_file () . path () . parent () . expect ("No parent") . join (input) } ; let svg = fs :: read_to_string (source) . expect ("Couldn't find file") ; let defs = { let defs_begin = svg . find ("<defs>") . expect ("Couldn't find <defs>") ; let defs_end = svg . find ("</defs>") . expect ("Couldn't find <defs>") ; & svg [defs_begin .. defs_end] } ; let defs_tokens = format ! ("r##\"{}\"##" , defs) ; defs_tokens . parse () . expect ("Couldn't convert strign to tokenstream") }